// Curated teaching sets, separate from the full illustrated dictionary.
const starter=new Set('apple|banana|pear|orange|lemon|strawberry|carrot|potato|tomato|bread|cheese|egg|cookie|cake|cup|spoon|fork|knife|plate|bowl|chair|bed|door|key|book|pencil|scissors|balloon|ball|bicycle|car|bus|dog|cat|cow|horse|fish|bird|duck|rabbit'.split('|'));
const everyday=new Set([...starter,...'monkey|lion|tiger|pig|goat|giraffe|elephant|mouse|hamster|bear|panda|chicken|penguin|owl|frog|turtle|snake|dolphin|shark|snail|butterfly|ant|bee|ladybug|spider|rose|sunflower|mushroom|grapes|watermelon|pineapple|peach|cherries|blueberries|corn|cucumber|broccoli|onion|peas|pancakes|pizza|sandwich|butter|candy|lollipop|train|tram|ambulance|fire engine|police car|taxi|tractor|motorcycle|ship|airplane|helicopter|rocket|jeans|scarf|mittens|coat|socks|dress|shorts|backpack|cap|mobile phone|telephone|laptop|pen|paintbrush|crayon|ruler|bin|hammer|ladder|shovel|mirror|window|toilet|shower|bathtub|broom|basket|bucket|soap|toothbrush|sponge|eraser'.split('|')]);
export const LEVELS=[['starter','First words','40 familiar words. A small place to start.'],['everyday','Everyday','Familiar objects and animals, with varied choices.'],['challenge','Challenge','All 323 words, including less common objects.']];
export function wordsForLevel(words,level='everyday'){const set=level==='starter'?starter:level==='challenge'?null:everyday;return set?words.filter(w=>set.has(w.word)):[...words];}
export function pictureGroup(word){const c=word.category||'';if(c.startsWith('animal'))return 'Animals';if(c.startsWith('food'))return 'Food';if(c.startsWith('transport'))return 'Vehicles';if(c.startsWith('plant'))return 'Nature';if(c==='clothing')return 'Clothes';if(['office','writing','toys'].includes(c))return 'School & play';if(['computer','phone','technology'].includes(c))return 'Technology';if(c==='musical-instrument')return 'Music';return 'Home & tools';}
// Interleave groups so a new session does not begin with 30 food questions.
export function variedWords(words){const groups=new Map();for(const w of words){const key=pictureGroup(w);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(w);}const out=[];for(let i=0;out.length<words.length;i++)for(const group of groups.values())if(group[i])out.push(group[i]);return out;}
